function loadSettings(){const data=localStorage.getItem('trashgame_settings');if(data){try{const parsed=JSON.parse(data);soundVolume=parsed.soundVolume!==undefined?parsed.soundVolume:70;musicVolume=parsed.musicVolume!==undefined?parsed.musicVolume:40;}catch(e){console.error("Error loading settings",e);}}
const soundSlider=document.getElementById('sliderSoundVolume');const musicSlider=document.getElementById('sliderMusicVolume');if(soundSlider)soundSlider.value=soundVolume;if(musicSlider)musicSlider.value=musicVolume;updateVolumeLabels();synth.setSoundVolume(soundVolume/100);synth.setMusicVolume(musicVolume/100);}
